css:
.label-container {
    width: 55mm;
    height: 25mm;
    padding: 0px;
    box-sizing: border-box;
    font-family: Arial, sans-serif;
    border: 0px solid #ddd;
    display: inline-block;
}

.itemcode-label {
    font-size: 18pt;
    font-weight: 700;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    margin-bottom: 3px;
}

.itemname-label {
    font-size: 8pt;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    margin-bottom: 3px;
}

.supplier-part-no {
    font-size: 8pt;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    margin-bottom: 3px;
}

.docname-label {
    font-size: 8pt;
    font-weight: normal;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    margin-bottom: 0px;
}

html:
{% for item in doc.items %}
    {% if item.custom_label_qty > 0 %}
        {% for i in range(item.custom_label_qty) %}
            <div class="label-container">
                <p class="itemcode-label">{{ item.item_code | default('N/A') }}</p>
                <p class="itemname-label">{{ item.item_name | default('No Name Available') }}</p>
                <p class="supplier-part-no">{{ item.supplier_part_no | default('No Supplier Part No') }}</p>
                <p class="docname-label">{{ doc.name | default('No Document Name') }}</p>
            </div>
        {% endfor %}
    {% endif %}
{% endfor %}
